--
-- Name: bulk_delete_categories(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_delete_categories(p_ids uuid[]) RETURNS TABLE(deleted_id uuid, blocked_id uuid, block_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_category_name text;
  v_product_count int;
BEGIN
  IF NOT (SELECT is_super_admin()) THEN
    RAISE EXCEPTION 'Solo super_admin puede ejecutar borrado masivo' USING ERRCODE = '42501';
  END IF;

  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('bulk_delete:categories'));

  FOREACH v_id IN ARRAY p_ids LOOP
    SELECT COALESCE(name_es, name_en, v_id::text) INTO v_category_name
    FROM product_categories WHERE id = v_id;

    IF v_category_name IS NULL THEN
      deleted_id := NULL; blocked_id := v_id; block_reason := 'not_found';
      RETURN NEXT;
      CONTINUE;
    END IF;

    SELECT count(*) INTO v_product_count FROM products WHERE category_id = v_id;

    IF v_product_count > 0 THEN
      deleted_id := NULL; blocked_id := v_id; block_reason := 'has_products';
      RETURN NEXT;
      CONTINUE;
    END IF;

    DELETE FROM product_categories WHERE id = v_id;

    INSERT INTO activity_logs (action, entity_type, entity_id, performed_by, description, metadata)
    VALUES (
      'category_deleted', 'category', v_id, COALESCE(auth.uid()::text, 'system'),
      'Categoría eliminada (bulk) - ' || v_category_name,
      jsonb_build_object('categoryId', v_id, 'categoryName', v_category_name, 'bulk', true)
    );

    deleted_id := v_id; blocked_id := NULL; block_reason := NULL;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION bulk_delete_categories(p_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bulk_delete_categories(p_ids uuid[]) IS 'Borrado masivo de categorias, exclusivo super_admin. Bloquea categorias con productos asociados (mismo criterio que deleteCategory() en productService.js).';


--
-- Name: bulk_delete_products(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_delete_products(p_ids uuid[]) RETURNS TABLE(deleted_id uuid, blocked_id uuid, block_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_product_name text;
  v_blocking_count int;
  v_prev_rpc text;
BEGIN
  IF NOT (SELECT is_super_admin()) THEN
    RAISE EXCEPTION 'Solo super_admin puede ejecutar borrado masivo' USING ERRCODE = '42501';
  END IF;

  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('bulk_delete:products'));

  FOREACH v_id IN ARRAY p_ids LOOP
    SELECT COALESCE(name_es, name_en, v_id::text) INTO v_product_name
    FROM products WHERE id = v_id;

    IF v_product_name IS NULL THEN
      deleted_id := NULL; blocked_id := v_id; block_reason := 'not_found';
      RETURN NEXT;
      CONTINUE;
    END IF;

    -- STEP 0 (TOCTOU): lock the batches and the product row BEFORE checking, so a concurrent
    -- reserve either committed already (and is seen below) or waits until the product is gone.
    PERFORM 1 FROM public.inventory i WHERE i.product_id = v_id ORDER BY i.id FOR UPDATE;
    PERFORM 1 FROM public.products p WHERE p.id = v_id FOR UPDATE;

    -- STEP 1: blocking orders (shared predicate: direct, via combo, via inventory, or a
    -- still-reserved allocation; fail-closed on unknown statuses).
    SELECT count(*) INTO v_blocking_count FROM public.get_product_blockers(v_id);

    IF v_blocking_count > 0 THEN
      deleted_id := NULL; blocked_id := v_id; block_reason := 'blocking_orders';
      RETURN NEXT;
      CONTINUE;
    END IF;

    -- STEP 2: clear inventory_id on the remaining (safe) orders
    UPDATE order_items oi SET inventory_id = NULL
    WHERE oi.inventory_id IN (SELECT id FROM inventory WHERE product_id = v_id)
      AND EXISTS (
        SELECT 1 FROM orders o WHERE o.id = oi.order_id
        AND o.status IN ('dispatched', 'delivered', 'completed', 'cancelled')
      );

    -- STEP 3: deactivate combos that contain this product
    UPDATE combo_products
    SET is_active = false, updated_at = now()
    WHERE is_active = true
      AND id IN (SELECT combo_id FROM combo_items WHERE product_id = v_id);

    -- STEP 4: delete combo_items references
    DELETE FROM combo_items WHERE product_id = v_id;

    -- STEP 5-6: snapshot the ledger sums, delete inventory_movements, then inventory (the
    -- BEFORE DELETE trigger snapshots every batch, including consumed allocations).
    PERFORM public._log_product_ledger_snapshot(v_id);

    v_prev_rpc := current_setting('app.stock_rpc', true);
    PERFORM set_config('app.stock_rpc', 'on', true);
    DELETE FROM inventory_movements
    WHERE inventory_id IN (SELECT id FROM inventory WHERE product_id = v_id);
    PERFORM set_config('app.stock_rpc', COALESCE(v_prev_rpc, 'off'), true);

    DELETE FROM inventory WHERE product_id = v_id;

    -- STEP 7: delete the product
    DELETE FROM products WHERE id = v_id;

    INSERT INTO activity_logs (action, entity_type, entity_id, performed_by, description, metadata)
    VALUES (
      'product_deleted', 'product', v_id, COALESCE(auth.uid()::text, 'system'),
      'Producto eliminado (bulk) - ' || v_product_name,
      jsonb_build_object('productId', v_id, 'productName', v_product_name, 'bulk', true)
    );

    deleted_id := v_id; blocked_id := NULL; block_reason := NULL;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION bulk_delete_products(p_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.bulk_delete_products(p_ids uuid[]) IS 'Borrado masivo de productos, exclusivo super_admin. Reusa la cascada de deleteProduct() (productService.js) dentro de una sola transaccion, con reporte parcial por item (deleted/blocked) y advisory lock por tipo de entidad.';


--
-- Name: calculate_order_total(numeric, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_order_total(p_subtotal numeric, p_shipping_zone_id uuid, p_discount_amount numeric DEFAULT 0) RETURNS numeric
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_shipping_cost numeric := 0;
  v_free_shipping boolean := false;
BEGIN
  SELECT shipping_cost, free_shipping
  INTO v_shipping_cost, v_free_shipping
  FROM public.shipping_zones
  WHERE id = p_shipping_zone_id AND is_active = true;

  IF v_free_shipping THEN
    v_shipping_cost := 0;
  END IF;

  RETURN (p_subtotal - COALESCE(p_discount_amount, 0)) + COALESCE(v_shipping_cost, 0);
END;
$$;


--
-- Name: consume_order_inventory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_order_inventory(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_order public.orders%ROWTYPE;
  v_result jsonb;
  v_count integer;
BEGIN
  IF v_uid IS NOT NULL AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'order_not_found', 'consumed', false);
  END IF;

  IF NOT v_order.stock_managed THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'legacy_order', 'consumed', false);
  END IF;
  IF v_order.payment_status IS DISTINCT FROM 'validated' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'payment_not_validated', 'consumed', false);
  END IF;

  IF v_order.status NOT IN ('pending', 'processing') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'order_not_active', 'consumed', false);
  END IF;

  IF NOT v_order.stock_reserved THEN
    v_result := public._reserve_order_locked(p_order_id);
    IF NOT (v_result ->> 'ok')::boolean THEN
      RETURN v_result || jsonb_build_object('consumed', false);
    END IF;
  END IF;

  v_count := public._consume_order_locked(p_order_id);

  IF v_count = 0 THEN
    -- Nothing was 'reserved'. Idempotent success only if the order really consumed before;
    -- otherwise the order is flagged reserved with no allocations (inconsistent): say so.
    IF EXISTS (SELECT 1 FROM public.order_stock_allocations a
                WHERE a.order_id = p_order_id AND a.state = 'consumed') THEN
      RETURN jsonb_build_object('ok', true, 'reason', 'already_consumed', 'consumed', false);
    END IF;
    RETURN jsonb_build_object('ok', false, 'reason', 'no_allocations', 'consumed', false);
  END IF;

  RETURN jsonb_build_object('ok', true, 'reason', NULL, 'consumed', true);
END;
$$;


--
-- Name: count_user_interactions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_user_interactions(p_user_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order_count integer := 0;
  v_remittance_count integer := 0;
  v_total integer := 0;
BEGIN
  SELECT COUNT(*) INTO v_order_count
  FROM public.orders
  WHERE user_id = p_user_id
  AND status = 'completed';

  SELECT COUNT(*) INTO v_remittance_count
  FROM public.remittances
  WHERE user_id = p_user_id
  AND payment_validated = true
  AND delivered_at IS NOT NULL;

  v_total := COALESCE(v_order_count, 0) + COALESCE(v_remittance_count, 0);

  RETURN v_total;
END;
$$;


--
-- Name: current_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_id() RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT auth.uid();
$$;


--
-- Name: current_user_is_enabled(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_is_enabled() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    is_user_enabled boolean;
BEGIN
    SELECT is_enabled INTO is_user_enabled
    FROM public.user_profiles
    WHERE id = auth.uid()
    LIMIT 1;

    RETURN COALESCE(is_user_enabled, false);
END;
$$;


--
-- Name: current_user_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_role() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    user_role text;
BEGIN
    SELECT role INTO user_role
    FROM public.user_profiles
    WHERE id = auth.uid()
    LIMIT 1;

    RETURN COALESCE(user_role, 'user');
END;
$$;


--
-- Name: delete_combo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_combo(p_combo_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_name text;
  v_blockers jsonb;
  v_items jsonb;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('delete:combo'));

  SELECT COALESCE(c.name_es, c.name_en, p_combo_id::text) INTO v_name
    FROM public.combo_products c WHERE c.id = p_combo_id;
  IF v_name IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  -- TOCTOU: component batches (a reserve of an order containing the combo needs them) and the
  -- combo row are locked BEFORE the blocker check.
  PERFORM 1 FROM public.inventory i
   WHERE i.product_id IN (SELECT ci.product_id FROM public.combo_items ci WHERE ci.combo_id = p_combo_id)
   ORDER BY i.id FOR UPDATE;
  PERFORM 1 FROM public.combo_products c WHERE c.id = p_combo_id FOR UPDATE;

  SELECT jsonb_agg(to_jsonb(b)) INTO v_blockers FROM public.get_combo_blockers(p_combo_id) b;
  IF v_blockers IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'blocking_orders', 'combo_name', v_name, 'blockers', v_blockers);
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('product_id', ci.product_id, 'quantity', ci.quantity)
                            ORDER BY ci.product_id), '[]'::jsonb)
    INTO v_items
    FROM public.combo_items ci WHERE ci.combo_id = p_combo_id;

  DELETE FROM public.combo_items ci WHERE ci.combo_id = p_combo_id;
  DELETE FROM public.combo_products c WHERE c.id = p_combo_id;

  INSERT INTO public.admin_destructive_ops_log (op_type, performed_by, details)
  VALUES ('combo_deleted', COALESCE(auth.uid()::text, 'system'),
          jsonb_build_object('combo_id', p_combo_id, 'name', v_name, 'items', v_items));

  RETURN jsonb_build_object('ok', true, 'combo_name', v_name);
END;
$$;


--
-- Name: delete_product(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_product(p_product_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_name text;
  v_blockers jsonb;
  v_combos jsonb;
  v_combo record;
  v_prev_rpc text;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  -- Same domain lock as the bulk delete: the two never interleave.
  PERFORM pg_advisory_xact_lock(hashtext('bulk_delete:products'));

  SELECT COALESCE(p.name_es, p.name_en, p_product_id::text) INTO v_name
    FROM public.products p WHERE p.id = p_product_id;
  IF v_name IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  -- TOCTOU: lock batches and product BEFORE the blocker check.
  PERFORM 1 FROM public.inventory i WHERE i.product_id = p_product_id ORDER BY i.id FOR UPDATE;
  PERFORM 1 FROM public.products p WHERE p.id = p_product_id FOR UPDATE;

  SELECT jsonb_agg(to_jsonb(b)) INTO v_blockers FROM public.get_product_blockers(p_product_id) b;
  IF v_blockers IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'blocking_orders', 'product_name', v_name, 'blockers', v_blockers);
  END IF;

  UPDATE public.order_items oi SET inventory_id = NULL
   WHERE oi.inventory_id IN (SELECT i.id FROM public.inventory i WHERE i.product_id = p_product_id);

  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', c.id, 'name', COALESCE(c.name_es, c.name_en, c.id::text))), '[]'::jsonb)
    INTO v_combos
    FROM public.combo_products c
   WHERE c.is_active
     AND c.id IN (SELECT ci.combo_id FROM public.combo_items ci WHERE ci.product_id = p_product_id);

  UPDATE public.combo_products c
     SET is_active = false, updated_at = now()
   WHERE c.is_active
     AND c.id IN (SELECT ci.combo_id FROM public.combo_items ci WHERE ci.product_id = p_product_id);

  FOR v_combo IN SELECT (e ->> 'id')::uuid AS id, e ->> 'name' AS name FROM jsonb_array_elements(v_combos) e LOOP
    INSERT INTO public.activity_logs (action, entity_type, entity_id, performed_by, description, metadata)
    VALUES ('combo_deactivated', 'combo', v_combo.id, COALESCE(auth.uid()::text, 'system'),
            'Combo desactivado - ' || v_combo.name || ' (producto eliminado: ' || v_name || ')',
            jsonb_build_object('comboId', v_combo.id, 'comboName', v_combo.name, 'reason', 'product_deleted',
                               'deletedProductId', p_product_id, 'deletedProductName', v_name));
  END LOOP;

  DELETE FROM public.combo_items ci WHERE ci.product_id = p_product_id;

  PERFORM public._log_product_ledger_snapshot(p_product_id);

  v_prev_rpc := current_setting('app.stock_rpc', true);
  PERFORM set_config('app.stock_rpc', 'on', true);
  DELETE FROM public.inventory_movements m
   WHERE m.inventory_id IN (SELECT i.id FROM public.inventory i WHERE i.product_id = p_product_id);
  PERFORM set_config('app.stock_rpc', COALESCE(v_prev_rpc, 'off'), true);

  DELETE FROM public.inventory i WHERE i.product_id = p_product_id;
  DELETE FROM public.products p WHERE p.id = p_product_id;

  INSERT INTO public.activity_logs (action, entity_type, entity_id, performed_by, description, metadata)
  VALUES ('product_deleted', 'product', p_product_id, COALESCE(auth.uid()::text, 'system'),
          'Producto eliminado - ' || v_name,
          jsonb_build_object('productId', p_product_id, 'productName', v_name, 'bulk', false));

  RETURN jsonb_build_object('ok', true, 'product_name', v_name, 'deactivated_combos', v_combos);
END;
$$;


--
-- Name: execute_platform_reset(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_platform_reset(p_confirmation text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_enabled boolean;
  v_n int;
  v_counts jsonb := '{}'::jsonb;
BEGIN
  IF NOT (SELECT is_super_admin()) THEN
    RAISE EXCEPTION 'Solo super_admin puede ejecutar el reset de plataforma' USING ERRCODE = '42501';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('platform_reset'));

  SELECT enabled INTO v_enabled FROM platform_reset_control WHERE id = 1 FOR UPDATE;

  IF NOT COALESCE(v_enabled, false) THEN
    RAISE EXCEPTION 'El reset no esta habilitado. Debe activarse el flag directamente en la base de datos (no desde la aplicacion).' USING ERRCODE = '42501';
  END IF;

  IF p_confirmation IS DISTINCT FROM 'RESETEAR' THEN
    RAISE EXCEPTION 'Texto de confirmacion invalido';
  END IF;

  DELETE FROM offer_usage WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('offer_usage', v_n);

  DELETE FROM cart_items WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('cart_items', v_n);

  DELETE FROM shopping_carts WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('shopping_carts', v_n);

  DELETE FROM remittances WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('remittances', v_n);

  DELETE FROM orders WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('orders', v_n);

  DELETE FROM recipients WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('recipients', v_n);

  DELETE FROM bank_accounts WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('bank_accounts', v_n);

  DELETE FROM offers WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('offers', v_n);

  DELETE FROM combo_products WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('combo_products', v_n);

  DELETE FROM inventory_movements WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('inventory_movements', v_n);

  DELETE FROM inventory WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('inventory', v_n);

  DELETE FROM zelle_transaction_history WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('zelle_transaction_history', v_n);

  DELETE FROM zelle_payment_stats WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('zelle_payment_stats', v_n);

  DELETE FROM notification_logs WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('notification_logs', v_n);

  DELETE FROM user_alerts WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('user_alerts', v_n);

  DELETE FROM site_visits WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('site_visits', v_n);

  DELETE FROM user_category_history WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('user_category_history', v_n);

  UPDATE zelle_accounts
  SET current_daily_amount = 0, current_monthly_amount = 0, last_used_at = NULL, updated_at = now()
  WHERE true;
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('zelle_accounts_reset', v_n);

  UPDATE user_profiles SET is_enabled = false, updated_at = now() WHERE role != 'super_admin';
  GET DIAGNOSTICS v_n = ROW_COUNT; v_counts := v_counts || jsonb_build_object('users_disabled', v_n);

  UPDATE platform_reset_control SET enabled = false, updated_at = now() WHERE id = 1;

  INSERT INTO admin_destructive_ops_log (op_type, performed_by, details)
  VALUES ('platform_reset', COALESCE(auth.uid()::text, 'system'), v_counts);

  RETURN v_counts;
END;
$$;


--
-- Name: FUNCTION execute_platform_reset(p_confirmation text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.execute_platform_reset(p_confirmation text) IS 'Reset a estado inicial funcional. Requiere super_admin, platform_reset_control.enabled=true (activable SOLO por SQL directo, nunca desde esta funcion) y confirmacion literal "RESETEAR". Todo-o-nada en una unica transaccion. Se auto-desarma (enabled=false) al terminar. DELETE/UPDATE usan "WHERE true" deliberadamente: el rol authenticator (PostgREST) tiene safeupdate cargado, que rechaza UPDATE/DELETE sin WHERE aunque el destino sea borrar/resetear todas las filas de la tabla.';


--
-- Name: expire_stale_order_reservations(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_stale_order_reservations(p_hours integer DEFAULT NULL::integer, p_proof_hours integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_ids uuid[];
  v_row record;
  v_released integer;
  v_count integer := 0;
  v_skipped integer := 0;
BEGIN
  IF v_uid IS NOT NULL AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  -- Explicit arguments are validated against the floors; NULL means "configured value"
  -- (floored too, so a bad direct edit of system_config cannot make the job over-eager).
  IF (p_hours IS NOT NULL AND p_hours < 6) OR (p_proof_hours IS NOT NULL AND p_proof_hours < 24) THEN
    RAISE EXCEPTION 'invalid_hours' USING ERRCODE = '22023';
  END IF;
  p_hours := COALESCE(p_hours, GREATEST(public._stock_policy_int('stock_unpaid_expiry_hours'), 6));
  p_proof_hours := COALESCE(p_proof_hours, GREATEST(public._stock_policy_int('stock_proof_expiry_hours'), 24));

  -- 1. Lock every candidate order first (skipping rows other transactions hold).
  SELECT array_agg(c.id ORDER BY c.id) INTO v_ids
    FROM (
      SELECT o.id
        FROM public.orders o
       WHERE o.stock_managed
         AND o.stock_reserved
         -- A pending branch only applies while the order still holds a 'reserved' allocation: a
         -- reopened order whose stock was already CONSUMED (cancelled without restock, then
         -- reopened) keeps stock_reserved = true but has nothing to release, and must not be
         -- cancelled as 'reservation_expired'.
         AND (
           -- orphan: cancelled but still holding a 'reserved' allocation
           (o.status = 'cancelled'
            AND EXISTS (SELECT 1 FROM public.order_stock_allocations a
                         WHERE a.order_id = o.id AND a.state = 'reserved'))
           OR (
             o.status = 'pending'
             AND EXISTS (SELECT 1 FROM public.order_stock_allocations a
                          WHERE a.order_id = o.id AND a.state = 'reserved')
             AND o.payment_status IN ('pending', 'rejected')
             AND GREATEST(
                   COALESCE(o.stock_reserved_at, o.created_at),
                   CASE WHEN o.payment_status = 'rejected'
                        THEN COALESCE(o.validated_at, '-infinity'::timestamptz)
                        ELSE '-infinity'::timestamptz END
                 ) < now() - make_interval(hours => p_hours)
           )
           OR (
             o.status = 'pending'
             AND EXISTS (SELECT 1 FROM public.order_stock_allocations a
                          WHERE a.order_id = o.id AND a.state = 'reserved')
             AND o.payment_status = 'proof_uploaded'
             AND COALESCE(o.stock_reserved_at, o.created_at)
                   < now() - make_interval(hours => p_proof_hours)
           )
         )
       ORDER BY o.id
         FOR UPDATE OF o SKIP LOCKED
    ) c;

  IF v_ids IS NULL THEN
    RETURN 0;
  END IF;

  -- 2. Then lock ALL their inventory rows in one globally ordered statement, so this
  --    batch job cannot deadlock against a concurrent multi-product reserve.
  PERFORM 1
     FROM public.inventory i
    WHERE i.id IN (
            SELECT a.inventory_id FROM public.order_stock_allocations a
             WHERE a.order_id = ANY (v_ids) AND a.state = 'reserved')
    ORDER BY i.id
      FOR UPDATE;

  -- 3. Cancel (when still unpaid) and release. Count only orders that actually changed.
  --    Each order runs in its own subtransaction: an order that cannot be expired (trigger
  --    failure, bad data) is skipped with a WARNING and rolled back alone, instead of
  --    aborting the whole sweep and starving every other order.
  FOR v_row IN
    SELECT o.id, o.status FROM public.orders o WHERE o.id = ANY (v_ids) ORDER BY o.id
  LOOP
    BEGIN
      IF v_row.status = 'pending' THEN
        UPDATE public.orders
           SET status = 'cancelled',
               payment_status = 'rejected',
               rejection_reason = 'reservation_expired',
               updated_at = now()
         WHERE id = v_row.id;
        PERFORM public._release_order_locked(v_row.id);
        v_count := v_count + 1;
      ELSE
        v_released := public._release_order_locked(v_row.id);
        IF v_released > 0 THEN
          v_count := v_count + 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_skipped := v_skipped + 1;
      RAISE WARNING 'expire_stale_order_reservations: order % skipped (%: %)', v_row.id, SQLSTATE, SQLERRM;
      -- The handler runs after the failed subtransaction was rolled back, so this row survives.
      INSERT INTO public.admin_destructive_ops_log (op_type, performed_by, details)
      VALUES ('stock_expiry_skipped', COALESCE(v_uid::text, 'system'),
              jsonb_build_object('order_id', v_row.id, 'sqlstate', SQLSTATE, 'sqlerrm', SQLERRM));
    END;
  END LOOP;

  -- One summary row per run that skipped something (clean runs write nothing). The integer
  -- return value stays "orders released/cancelled" for compatibility with the cron call.
  IF v_skipped > 0 THEN
    INSERT INTO public.admin_destructive_ops_log (op_type, performed_by, details)
    VALUES ('stock_expiry_run', COALESCE(v_uid::text, 'system'),
            jsonb_build_object('released', v_count, 'skipped', v_skipped));
  END IF;

  RETURN v_count;
END;
$$;


--
-- Name: generate_order_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_order_number() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN 'ORD-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || LPAD(NEXTVAL('public.order_sequence')::TEXT, 4, '0');
END;
$$;


--
-- Name: generate_remittance_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_remittance_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.remittance_number IS NULL THEN
    NEW.remittance_number := 'REM-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(nextval('remittance_number_seq')::TEXT, 6, '0');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: get_category_from_interactions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_category_from_interactions(p_interactions integer) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_category text := 'regular';
BEGIN
  IF p_interactions >= (SELECT interaction_threshold FROM public.category_rules WHERE category_name = 'vip') THEN
    v_category := 'vip';
  ELSIF p_interactions >= (SELECT interaction_threshold FROM public.category_rules WHERE category_name = 'pro') THEN
    v_category := 'pro';
  ELSE
    v_category := 'regular';
  END IF;

  RETURN v_category;
END;
$$;


--
-- Name: get_combo_blockers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_combo_blockers(p_combo_id uuid) RETURNS TABLE(order_id uuid, order_number text, status text, payment_status text, via text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT DISTINCT ON (o.id)
         o.id, o.order_number::text, o.status::text, o.payment_status::text,
         CASE WHEN o.status IS NULL OR o.status NOT IN ('dispatched', 'delivered', 'completed', 'cancelled')
              THEN 'direct' ELSE 'allocation' END
    FROM public.order_items oi
    JOIN public.orders o ON o.id = oi.order_id
   WHERE oi.item_id = p_combo_id
     AND (
       o.status IS NULL
       OR o.status NOT IN ('dispatched', 'delivered', 'completed', 'cancelled')
       OR EXISTS (
         SELECT 1
           FROM public.order_stock_allocations a
          WHERE a.order_id = o.id
            AND a.state = 'reserved'
            AND a.inventory_id IN (
                  SELECT inv.id
                    FROM public.combo_items ci
                    JOIN public.inventory inv ON inv.product_id = ci.product_id
                   WHERE ci.combo_id = p_combo_id))
     )
   ORDER BY o.id;
END;
$$;


--
-- Name: get_daily_operational_cost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_daily_operational_cost() RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  total_daily_cost DECIMAL := 0;
  cost_record RECORD;
BEGIN
  IF NOT is_admin_user() THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;
  FOR cost_record IN
    SELECT amount, frequency FROM operational_costs WHERE is_active = true
  LOOP
    CASE cost_record.frequency
      WHEN 'daily' THEN total_daily_cost := total_daily_cost + cost_record.amount;
      WHEN 'weekly' THEN total_daily_cost := total_daily_cost + (cost_record.amount / 7);
      WHEN 'biweekly' THEN total_daily_cost := total_daily_cost + (cost_record.amount / 14);
      WHEN 'monthly' THEN total_daily_cost := total_daily_cost + (cost_record.amount / 30);
      WHEN 'yearly' THEN total_daily_cost := total_daily_cost + (cost_record.amount / 365);
    END CASE;
  END LOOP;
  RETURN total_daily_cost;
END;
$$;


--
-- Name: get_low_stock_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_low_stock_count() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*)::integer
  FROM public.inventory i
  JOIN public.products p ON p.id = i.product_id
  WHERE i.available_quantity <= p.min_stock_alert
  AND i.available_quantity > 0
  AND i.is_active = true;
$$;


--
-- Name: get_my_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT role FROM user_profiles WHERE id = auth.uid() LIMIT 1),
    'user'
  )
$$;


--
-- Name: get_pending_orders_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_pending_orders_count() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COUNT(*)::integer
  FROM public.orders
  WHERE status = 'pending' OR payment_status = 'pending';
$$;


--
-- Name: get_product_blockers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_blockers(p_product_id uuid) RETURNS TABLE(order_id uuid, order_number text, status text, payment_status text, via text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH inv AS (
    SELECT i.id FROM public.inventory i WHERE i.product_id = p_product_id
  ),
  hits AS (
    SELECT oi.order_id AS oid, 'direct'::text AS via, 1 AS prio
      FROM public.order_items oi
     WHERE oi.item_id = p_product_id
    UNION ALL
    SELECT oi.order_id, 'combo', 2
      FROM public.order_items oi
     WHERE oi.item_id IN (SELECT ci.combo_id FROM public.combo_items ci WHERE ci.product_id = p_product_id)
    UNION ALL
    SELECT oi.order_id, 'inventory', 3
      FROM public.order_items oi
     WHERE oi.inventory_id IN (SELECT inv.id FROM inv)
    UNION ALL
    SELECT a.order_id, 'allocation', 4
      FROM public.order_stock_allocations a
     WHERE a.state = 'reserved'
       AND a.inventory_id IN (SELECT inv.id FROM inv)
  )
  SELECT DISTINCT ON (o.id) o.id, o.order_number::text, o.status::text, o.payment_status::text, h.via
    FROM hits h
    JOIN public.orders o ON o.id = h.oid
   WHERE h.via = 'allocation'
      OR o.status IS NULL
      OR o.status NOT IN ('dispatched', 'delivered', 'completed', 'cancelled')
   ORDER BY o.id, h.prio;
END;
$$;


--
-- Name: get_recipient_bank_account_full(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recipient_bank_account_full(p_recipient_bank_account_id uuid) RETURNS TABLE(recipient_bank_account_id uuid, bank_name text, account_type text, currency_code text, account_holder_name text, account_number_full text, account_number_last4 text, is_default boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_admin_user() THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  RETURN QUERY
  SELECT
    rba.id AS recipient_bank_account_id,
    b.name AS bank_name,
    at.name AS account_type,
    c.code AS currency_code,
    ba.account_holder_name,
    ba.account_number_full,
    ba.account_number_last4,
    rba.is_default
  FROM public.recipient_bank_accounts rba
  INNER JOIN public.bank_accounts ba ON ba.id = rba.bank_account_id
  INNER JOIN public.banks b ON b.id = ba.bank_id
  INNER JOIN public.account_types at ON at.id = ba.account_type_id
  INNER JOIN public.currencies c ON c.id = ba.currency_id
  WHERE rba.id = p_recipient_bank_account_id
    AND rba.is_active = true
    AND ba.is_active = true
    AND ba.deleted_at IS NULL;
END;
$$;


--
-- Name: FUNCTION get_recipient_bank_account_full(p_recipient_bank_account_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_recipient_bank_account_full(p_recipient_bank_account_id uuid) IS 'Retrieve full account number for a recipient bank account. SECURITY: Only callable by admin/super_admin roles. Used for payment processing.';


--
-- Name: get_remittance_bank_accounts_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_remittance_bank_accounts_admin(p_remittance_id uuid) RETURNS TABLE(remittance_id uuid, recipient_name text, recipient_phone text, bank_name text, account_type text, currency_code text, account_holder_name text, account_number_full text, account_number_last4 text, delivery_amount numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_admin_user() THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  RETURN QUERY
  SELECT
    r.id AS remittance_id,
    rec.full_name AS recipient_name,
    rec.phone AS recipient_phone,
    b.name AS bank_name,
    at.name AS account_type,
    c.code AS currency_code,
    ba.account_holder_name,
    ba.account_number_full,
    ba.account_number_last4,
    r.delivery_amount
  FROM public.remittances r
  INNER JOIN public.recipients rec ON rec.id = r.recipient_id
  LEFT JOIN public.remittance_bank_transfers rbt ON rbt.remittance_id = r.id
  LEFT JOIN public.recipient_bank_accounts rba ON rba.id = rbt.recipient_bank_account_id
  LEFT JOIN public.bank_accounts ba ON ba.id = rba.bank_account_id
  LEFT JOIN public.banks b ON b.id = ba.bank_id
  LEFT JOIN public.account_types at ON at.id = ba.account_type_id
  LEFT JOIN public.currencies c ON c.id = ba.currency_id
  WHERE r.id = p_remittance_id;
END;
$$;


--
-- Name: FUNCTION get_remittance_bank_accounts_admin(p_remittance_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_remittance_bank_accounts_admin(p_remittance_id uuid) IS 'Get complete bank account details for a remittance including full account numbers. SECURITY: Admin/super_admin only. Used for payment processing dashboard.';


--
-- Name: get_shipping_cost_for_location(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_shipping_cost_for_location(p_province_name text, p_municipality_name text DEFAULT NULL::text) RETURNS TABLE(zone_id uuid, shipping_cost numeric, free_shipping boolean, is_municipality_specific boolean)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_municipality_name IS NOT NULL THEN
    RETURN QUERY
    SELECT
      sz.id,
      sz.shipping_cost,
      sz.free_shipping,
      true as is_municipality_specific
    FROM public.shipping_zones sz
    WHERE sz.province_name = p_province_name
      AND sz.municipality_name = p_municipality_name
      AND sz.is_active = true
    LIMIT 1;

    IF FOUND THEN
      RETURN;
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    sz.id,
    sz.shipping_cost,
    sz.free_shipping,
    false as is_municipality_specific
  FROM public.shipping_zones sz
  WHERE sz.province_name = p_province_name
    AND sz.municipality_name IS NULL
    AND sz.is_active = true
  LIMIT 1;
END;
$$;


--
-- Name: FUNCTION get_shipping_cost_for_location(p_province_name text, p_municipality_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_shipping_cost_for_location(p_province_name text, p_municipality_name text) IS 'Get shipping cost for a location. Tries municipality-specific first, then falls back to province default.';


--
-- Name: get_stock_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_stock_policy() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'unpaid_hours', public._stock_policy_int('stock_unpaid_expiry_hours'),
    'proof_hours', public._stock_policy_int('stock_proof_expiry_hours'),
    'max_open_reservations', public._stock_policy_int('stock_max_open_reservations'),
    'defaults', jsonb_build_object('unpaid_hours', 48, 'proof_hours', 168, 'max_open_reservations', 5),
    'bounds', jsonb_build_object(
      'unpaid_hours', jsonb_build_object('min', 6, 'max', 720),
      'proof_hours', jsonb_build_object('min', 24, 'max', 2160),
      'max_open_reservations', jsonb_build_object('min', 1, 'max', 50)
    )
  );
END;
$$;


