--
-- Name: guard_inventory_movements_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_inventory_movements_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('app.stock_rpc', true) IS NOT DISTINCT FROM 'on'
     OR current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'inventory_movements is a ledger: rows are deleted only by the delete functions'
    USING ERRCODE = '42501';
END;
$$;


--
-- Name: guard_inventory_reserved_edit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_inventory_reserved_edit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_setting('app.stock_rpc', true) IS NOT DISTINCT FROM 'on'
     OR current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  IF (TG_OP = 'INSERT' AND COALESCE(NEW.reserved_quantity, 0) <> 0)
     OR (TG_OP = 'UPDATE' AND NEW.reserved_quantity IS DISTINCT FROM OLD.reserved_quantity) THEN
    RAISE EXCEPTION 'reserved_quantity is managed by the stock reservation functions'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_order_items_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_order_items_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin')
     OR auth.uid() IS NULL
     OR public.is_admin_user()
     OR public.is_super_admin() THEN
    RETURN NEW;
  END IF;

  -- FOR SHARE: the check and the insert are one atomic step against reserve/cancel, which
  -- take the order row FOR UPDATE (the FK key-share lock already conflicted with it;
  -- this makes the dependency explicit instead of incidental).
  PERFORM 1
     FROM public.orders o
    WHERE o.id = NEW.order_id
      AND o.status = 'pending'
      AND NOT o.stock_reserved
      FOR SHARE OF o;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'order_items_insert_forbidden: order is not an open unreserved order'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_orders_owner_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_orders_owner_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  c_staff_only constant text[] := ARRAY[
    'validated_by', 'validated_at', 'rejection_reason',
    'delivered_at', 'delivery_notes', 'delivery_proof_url',
    'processing_started_at', 'shipped_at', 'completed_at',
    'dispatched_by', 'dispatched_at', 'actual_delivery',
    'tracking_number', 'admin_notes'
  ];
  v_new jsonb;
  v_key text;
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin')
     OR auth.uid() IS NULL
     OR public.is_admin_user()
     OR public.is_super_admin() THEN
    RETURN NEW;
  END IF;

  IF NEW.user_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'orders_owner_insert_forbidden: user_id' USING ERRCODE = '42501';
  END IF;

  IF NEW.status IS DISTINCT FROM 'pending' THEN
    RAISE EXCEPTION 'orders_owner_insert_forbidden: status' USING ERRCODE = '42501';
  END IF;

  IF NEW.payment_status IS DISTINCT FROM 'pending' THEN
    RAISE EXCEPTION 'orders_owner_insert_forbidden: payment_status' USING ERRCODE = '42501';
  END IF;

  v_new := to_jsonb(NEW);
  FOREACH v_key IN ARRAY c_staff_only LOOP
    IF (v_new -> v_key) IS NOT NULL AND (v_new -> v_key) <> 'null'::jsonb THEN
      RAISE EXCEPTION 'orders_owner_insert_forbidden: %', v_key USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: guard_orders_owner_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_orders_owner_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  c_allowed constant text[] := ARRAY[
    'payment_proof_url', 'payment_reference', 'payment_status',
    'rejection_reason', 'status', 'updated_at'
  ];
  c_proof constant text[] := ARRAY['payment_proof_url', 'payment_reference'];
  v_new jsonb;
  v_old jsonb;
  v_key text;
  v_cancel boolean := false;
  v_reopen boolean := false;
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin')
     OR auth.uid() IS NULL
     OR public.is_admin_user()
     OR public.is_super_admin() THEN
    RETURN NEW;
  END IF;

  v_new := to_jsonb(NEW);
  v_old := to_jsonb(OLD);

  FOR v_key IN
    SELECT k FROM jsonb_object_keys(v_new) AS k WHERE k <> ALL (c_allowed)
  LOOP
    IF (v_new -> v_key) IS DISTINCT FROM (v_old -> v_key) THEN
      RAISE EXCEPTION 'orders_owner_update_forbidden: column %', v_key USING ERRCODE = '42501';
    END IF;
  END LOOP;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF OLD.status = 'pending' AND NEW.status = 'cancelled'
       AND OLD.payment_status IS DISTINCT FROM 'validated' THEN
      v_cancel := true;
    ELSIF OLD.status = 'cancelled' AND NEW.status = 'pending'
       AND OLD.payment_status IN ('pending', 'rejected', 'proof_uploaded') THEN
      v_reopen := true;
    ELSE
      RAISE EXCEPTION 'orders_owner_update_forbidden: column status' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NEW.payment_status IS DISTINCT FROM OLD.payment_status THEN
    IF v_cancel AND NEW.payment_status = 'rejected' THEN
      NULL;
    ELSIF v_reopen AND NEW.payment_status = 'pending' THEN
      NULL;
    ELSIF NOT v_cancel AND NOT v_reopen
       AND OLD.status = 'pending'
       AND OLD.payment_status IN ('pending', 'rejected')
       AND NEW.payment_status = 'proof_uploaded' THEN
      NULL;
    ELSE
      RAISE EXCEPTION 'orders_owner_update_forbidden: column payment_status' USING ERRCODE = '42501';
    END IF;
  END IF;

  FOREACH v_key IN ARRAY c_proof LOOP
    IF (v_new -> v_key) IS DISTINCT FROM (v_old -> v_key)
       AND NOT (
         OLD.status = 'pending' AND NEW.status = 'pending'
         AND OLD.payment_status IN ('pending', 'rejected', 'proof_uploaded')
         AND NEW.payment_status = 'proof_uploaded'
       ) THEN
      RAISE EXCEPTION 'orders_owner_update_forbidden: column %', v_key USING ERRCODE = '42501';
    END IF;
  END LOOP;

  IF NEW.rejection_reason IS DISTINCT FROM OLD.rejection_reason
     AND NOT (
       v_cancel
       OR (
         NEW.rejection_reason IS NULL
         AND OLD.status = 'pending' AND NEW.status = 'pending'
         AND NEW.payment_status = 'proof_uploaded'
       )
     ) THEN
    RAISE EXCEPTION 'orders_owner_update_forbidden: column rejection_reason' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_orders_stock_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_orders_stock_columns() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin')
     OR auth.uid() IS NULL
     OR public.is_admin_user()
     OR public.is_super_admin() THEN
    RETURN NEW;
  END IF;

  NEW.stock_managed := true;
  NEW.stock_reserved := false;
  NEW.stock_reserved_at := NULL;
  RETURN NEW;
END;
$$;


--
-- Name: guard_payment_method_enabled(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_payment_method_enabled() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_flow text;
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin')
     OR auth.uid() IS NULL
     OR public.is_admin_user()
     OR public.is_super_admin() THEN
    RETURN NEW;
  END IF;

  v_flow := CASE TG_TABLE_NAME
    WHEN 'orders' THEN 'orders'
    WHEN 'remittances' THEN 'remittances'
    ELSE NULL
  END;

  PERFORM pg_advisory_xact_lock_shared(hashtext('payment_methods'));

  IF v_flow IS NULL OR NOT public.payment_method_allowed(NEW.payment_method, v_flow) THEN
    RAISE EXCEPTION 'payment_method_disabled'
      USING ERRCODE = 'P0001',
            DETAIL = format('table=%s method=%s', TG_TABLE_NAME, COALESCE(NEW.payment_method, 'NULL'));
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: guard_platform_reset_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_platform_reset_lock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(hashtext('platform_reset'));
  RETURN NEW;
END;
$$;


--
-- Name: guard_remittance_owner_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_remittance_owner_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  c_staff_only constant text[] := ARRAY[
    'payment_validated_at', 'payment_validated_by', 'payment_rejection_reason',
    'delivery_proof_url', 'delivery_notes_admin', 'delivered_to_name',
    'delivered_to_id', 'delivered_at', 'delivered_by',
    'processing_started_at', 'completed_at',
    'cancelled_at', 'cancellation_reason', 'cancelled_by'
  ];
  v_new jsonb;
  v_key text;
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin')
     OR auth.uid() IS NULL
     OR public.is_admin_user()
     OR public.is_super_admin() THEN
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM 'payment_pending' THEN
    RAISE EXCEPTION 'remittance_owner_insert_forbidden: status' USING ERRCODE = '42501';
  END IF;

  IF NEW.payment_validated IS TRUE THEN
    RAISE EXCEPTION 'remittance_owner_insert_forbidden: payment_validated' USING ERRCODE = '42501';
  END IF;

  v_new := to_jsonb(NEW);
  FOREACH v_key IN ARRAY c_staff_only LOOP
    IF (v_new -> v_key) IS NOT NULL AND (v_new -> v_key) <> 'null'::jsonb THEN
      RAISE EXCEPTION 'remittance_owner_insert_forbidden: %', v_key USING ERRCODE = '42501';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: guard_remittance_owner_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_remittance_owner_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  c_allowed constant text[] := ARRAY[
    'payment_proof_url', 'payment_reference', 'payment_proof_notes',
    'payment_proof_uploaded_at', 'payer_phone', 'updated_at',
    'status', 'cancelled_at', 'cancelled_by', 'cancellation_reason'
  ];
  c_proof constant text[] := ARRAY[
    'payment_proof_url', 'payment_reference', 'payment_proof_notes',
    'payment_proof_uploaded_at', 'payer_phone'
  ];
  c_cancel constant text[] := ARRAY['cancelled_at', 'cancelled_by', 'cancellation_reason'];
  v_new jsonb;
  v_old jsonb;
  v_key text;
BEGIN
  IF current_user IN ('postgres', 'service_role', 'supabase_admin')
     OR auth.uid() IS NULL
     OR public.is_admin_user()
     OR public.is_super_admin() THEN
    RETURN NEW;
  END IF;
  v_new := to_jsonb(NEW);
  v_old := to_jsonb(OLD);
  FOR v_key IN
    SELECT k FROM jsonb_object_keys(v_new) AS k WHERE k <> ALL (c_allowed)
  LOOP
    IF (v_new -> v_key) IS DISTINCT FROM (v_old -> v_key) THEN
      RAISE EXCEPTION 'remittance_owner_update_forbidden: column %', v_key USING ERRCODE = '42501';
    END IF;
  END LOOP;
  FOREACH v_key IN ARRAY c_proof LOOP
    IF (v_new -> v_key) IS DISTINCT FROM (v_old -> v_key)
       AND OLD.status NOT IN ('payment_pending', 'payment_rejected') THEN
      RAISE EXCEPTION 'remittance_owner_update_forbidden: column %', v_key USING ERRCODE = '42501';
    END IF;
  END LOOP;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT (
      (OLD.status IN ('payment_pending', 'payment_rejected') AND NEW.status = 'payment_proof_uploaded')
      OR (OLD.status IN ('payment_pending', 'payment_rejected', 'payment_proof_uploaded') AND NEW.status = 'cancelled')
    ) THEN
      RAISE EXCEPTION 'remittance_owner_update_forbidden: column status' USING ERRCODE = '42501';
    END IF;
  END IF;
  FOREACH v_key IN ARRAY c_cancel LOOP
    IF (v_new -> v_key) IS DISTINCT FROM (v_old -> v_key)
       AND NOT (NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM 'cancelled') THEN
      RAISE EXCEPTION 'remittance_owner_update_forbidden: column %', v_key USING ERRCODE = '42501';
    END IF;
  END LOOP;
  IF NEW.cancelled_by IS DISTINCT FROM OLD.cancelled_by
     AND NEW.cancelled_by IS NOT NULL
     AND NEW.cancelled_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'remittance_owner_update_forbidden: column cancelled_by' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    user_role_value text;
BEGIN
    IF NEW.email IN ('jtheoden@gmail.com', 'jtheoden@googlemail.com', 'superadmin@test.com') THEN
        user_role_value := 'super_admin';
    ELSIF NEW.email = 'admin@test.com' THEN
        user_role_value := 'admin';
    ELSE
        user_role_value := 'user';
    END IF;

    INSERT INTO public.user_profiles (
        id,
        user_id,
        email,
        role,
        full_name,
        avatar_url,
        is_enabled
    )
    VALUES (
        NEW.id,
        NEW.id,
        NEW.email,
        user_role_value,
        COALESCE(
            NEW.raw_user_meta_data->>'full_name',
            NEW.raw_user_meta_data->>'name',
            split_part(NEW.email, '@', 1)
        ),
        COALESCE(
            NEW.raw_user_meta_data->>'avatar_url',
            NEW.raw_user_meta_data->>'picture',
            'https://api.dicebear.com/7.x/avataaars/svg?seed=' || encode(sha256(NEW.email::bytea), 'hex')
        ),
        true
    )
    ON CONFLICT (id) DO UPDATE
    SET
        email = EXCLUDED.email,
        role = EXCLUDED.role,
        full_name = COALESCE(EXCLUDED.full_name, user_profiles.full_name),
        avatar_url = COALESCE(EXCLUDED.avatar_url, user_profiles.avatar_url),
        updated_at = NOW();

    RETURN NEW;
END;
$$;


--
-- Name: is_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(role = 'admin', false)
  FROM public.user_profiles
  WHERE id = auth.uid()
  LIMIT 1;
$$;


--
-- Name: is_admin_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_admin_user() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = auth.uid()
    AND role IN ('admin', 'super_admin')
    AND is_enabled = true
  );
END;
$$;


--
-- Name: FUNCTION is_admin_user(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_admin_user() IS 'Verifica si el usuario autenticado actual es admin o super_admin';


--
-- Name: is_manager(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_manager() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(role = 'manager', false)
  FROM public.user_profiles
  WHERE id = auth.uid()
  LIMIT 1;
$$;


--
-- Name: is_super_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_super_admin() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN COALESCE(
    (SELECT role = 'super_admin' AND is_enabled = true FROM public.user_profiles WHERE id = auth.uid() LIMIT 1),
    false
  );
END;
$$;


--
-- Name: list_payment_methods_public(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_payment_methods_public() RETURNS TABLE(code text, available boolean, enabled_for_orders boolean, enabled_for_remittances boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT pm.code, pm.available, pm.enabled_for_orders, pm.enabled_for_remittances
    FROM public.payment_methods pm
   ORDER BY pm.code;
$$;


--
-- Name: list_zelle_accounts_public(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_zelle_accounts_public(p_usage text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric) RETURNS TABLE(id uuid, account_name text, account_holder text, email text, phone text, priority_order integer, for_products boolean, for_remittances boolean, available boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_usage IS NOT NULL AND p_usage NOT IN ('products', 'remittances') THEN
    RAISE EXCEPTION 'invalid p_usage: %', p_usage USING ERRCODE = '22023';
  END IF;
  IF p_amount IS NOT NULL AND p_amount < 0 THEN
    RAISE EXCEPTION 'p_amount must not be negative' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    za.id,
    za.account_name,
    za.account_holder,
    CASE WHEN za.show_email THEN za.email ELSE NULL END,
    CASE WHEN za.show_phone THEN za.phone ELSE NULL END,
    za.priority_order,
    za.for_products,
    za.for_remittances,
    cap.fits
  FROM zelle_accounts za
  JOIN public.zelle_account_capacity(p_amount) cap ON cap.account_id = za.id
  WHERE za.is_active = true
    AND (
      p_usage IS NULL
      OR (p_usage = 'products' AND za.for_products = true)
      OR (p_usage = 'remittances' AND za.for_remittances = true)
    )
  ORDER BY za.priority_order ASC, za.account_name ASC;
END;
$$;


--
-- Name: orders_with_consumed_stock(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.orders_with_consumed_stock(p_order_ids uuid[]) RETURNS TABLE(order_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT o.id
    FROM public.orders o
   WHERE o.id = ANY (p_order_ids)
     AND o.status = 'cancelled'
     AND EXISTS (SELECT 1 FROM public.order_stock_allocations a
                  WHERE a.order_id = o.id AND a.state = 'consumed');
END;
$$;


--
-- Name: payment_method_allowed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_method_allowed(p_code text, p_flow text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN COALESCE(
    (
      SELECT pm.available AND CASE p_flow
               WHEN 'orders' THEN pm.enabled_for_orders
               WHEN 'remittances' THEN pm.enabled_for_remittances
               ELSE false
             END
        FROM public.payment_methods pm
       WHERE pm.code = p_code
    ),
    false
  );
END;
$$;


--
-- Name: preview_bulk_delete_categories(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_bulk_delete_categories(p_ids uuid[]) RETURNS TABLE(id uuid, name text, can_delete boolean, block_reason text, products_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_category_name text;
  v_product_count int;
BEGIN
  IF NOT (SELECT is_super_admin()) THEN
    RAISE EXCEPTION 'Solo super_admin puede previsualizar el borrado masivo' USING ERRCODE = '42501';
  END IF;

  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  FOREACH v_id IN ARRAY p_ids LOOP
    SELECT COALESCE(name_es, name_en, v_id::text) INTO v_category_name
    FROM product_categories WHERE id = v_id;

    IF v_category_name IS NULL THEN
      id := v_id; name := NULL; can_delete := false; block_reason := 'not_found'; products_count := 0;
      RETURN NEXT;
      CONTINUE;
    END IF;

    SELECT count(*) INTO v_product_count FROM products WHERE category_id = v_id;

    id := v_id;
    name := v_category_name;
    products_count := v_product_count;

    IF v_product_count > 0 THEN
      can_delete := false;
      block_reason := 'has_products';
    ELSE
      can_delete := true;
      block_reason := NULL;
    END IF;

    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION preview_bulk_delete_categories(p_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.preview_bulk_delete_categories(p_ids uuid[]) IS 'Preview de solo lectura de bulk_delete_categories: mismos chequeos, sin escribir.';


--
-- Name: preview_bulk_delete_products(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_bulk_delete_products(p_ids uuid[]) RETURNS TABLE(id uuid, name text, can_delete boolean, block_reason text, blocking_orders_count integer, combos_to_deactivate integer, inventory_rows integer, inventory_movements integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id uuid;
  v_product_name text;
  v_blocking_count int;
BEGIN
  IF NOT (SELECT is_super_admin()) THEN
    RAISE EXCEPTION 'Solo super_admin puede previsualizar el borrado masivo' USING ERRCODE = '42501';
  END IF;

  IF p_ids IS NULL OR array_length(p_ids, 1) IS NULL THEN
    RETURN;
  END IF;

  FOREACH v_id IN ARRAY p_ids LOOP
    SELECT COALESCE(name_es, name_en, v_id::text) INTO v_product_name
    FROM products WHERE products.id = v_id;

    IF v_product_name IS NULL THEN
      id := v_id; name := NULL; can_delete := false; block_reason := 'not_found';
      blocking_orders_count := 0; combos_to_deactivate := 0; inventory_rows := 0; inventory_movements := 0;
      RETURN NEXT;
      CONTINUE;
    END IF;

    SELECT count(*) INTO v_blocking_count FROM public.get_product_blockers(v_id);

    id := v_id;
    name := v_product_name;
    blocking_orders_count := v_blocking_count;

    SELECT count(*) INTO combos_to_deactivate
    FROM combo_products
    WHERE is_active = true
      AND combo_products.id IN (SELECT combo_id FROM combo_items WHERE product_id = v_id);

    SELECT count(*) INTO inventory_rows FROM inventory WHERE product_id = v_id;

    SELECT count(*) INTO inventory_movements
    FROM public.inventory_movements im
    WHERE im.inventory_id IN (SELECT inv.id FROM inventory inv WHERE inv.product_id = v_id);

    IF v_blocking_count > 0 THEN
      can_delete := false;
      block_reason := 'blocking_orders';
    ELSE
      can_delete := true;
      block_reason := NULL;
    END IF;

    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: FUNCTION preview_bulk_delete_products(p_ids uuid[]); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.preview_bulk_delete_products(p_ids uuid[]) IS 'Preview de solo lectura de bulk_delete_products: mismos chequeos, sin escribir. Reporta por producto si es eliminable y el impacto en cascada (combos, inventario).';


--
-- Name: purge_old_activity_logs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.purge_old_activity_logs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  DELETE FROM public.activity_logs WHERE created_at < now() - interval '90 days';
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: remittances; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.remittances (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    remittance_number character varying(50) NOT NULL,
    user_id uuid NOT NULL,
    remittance_type_id uuid NOT NULL,
    amount_sent numeric(12,2) NOT NULL,
    exchange_rate numeric(12,4) NOT NULL,
    commission_percentage numeric(5,2) NOT NULL,
    commission_fixed numeric(10,2) NOT NULL,
    commission_total numeric(10,2) NOT NULL,
    amount_to_deliver numeric(12,2) NOT NULL,
    currency_sent character varying(10) NOT NULL,
    currency_delivered character varying(10) NOT NULL,
    recipient_name character varying(200) NOT NULL,
    recipient_phone character varying(20) NOT NULL,
    recipient_id_number character varying(50),
    recipient_address text,
    recipient_province character varying(100),
    recipient_municipality character varying(100),
    delivery_notes text,
    payment_proof_url text,
    payment_reference character varying(200),
    payment_proof_uploaded_at timestamp with time zone,
    payment_proof_notes text,
    payment_validated boolean DEFAULT false,
    payment_validated_at timestamp with time zone,
    payment_validated_by uuid,
    payment_rejection_reason text,
    delivery_proof_url text,
    delivery_notes_admin text,
    delivered_to_name character varying(200),
    delivered_to_id character varying(50),
    delivered_at timestamp with time zone,
    delivered_by uuid,
    status character varying(50) DEFAULT 'payment_pending'::character varying NOT NULL,
    processing_started_at timestamp with time zone,
    completed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancellation_reason text,
    cancelled_by uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    recipient_id uuid,
    recipient_address_id uuid,
    zelle_account_id uuid,
    zelle_transaction_id uuid,
    recipient_email character varying(255),
    recipient_bank_account_id uuid,
    offer_id uuid,
    discount_amount numeric(10,2) DEFAULT 0,
    payer_phone character varying(30),
    delivery_cost numeric(12,2) DEFAULT 0 NOT NULL,
    shipping_zone_id uuid,
    payment_method text DEFAULT 'zelle'::text NOT NULL,
    CONSTRAINT remittances_delivery_cost_nonnegative CHECK ((delivery_cost >= (0)::numeric)),
    CONSTRAINT remittances_payer_phone_length_check CHECK (((payer_phone IS NULL) OR ((char_length(btrim((payer_phone)::text)) >= 7) AND (char_length(btrim((payer_phone)::text)) <= 30)))),
    CONSTRAINT remittances_payment_method_check CHECK ((payment_method = ANY (ARRAY['zelle'::text, 'bizum'::text])))
);


--
-- Name: TABLE remittances; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.remittances IS 'Órdenes de remesas de usuarios';


--
-- Name: COLUMN remittances.remittance_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittances.remittance_number IS 'Número único de remesa (REM-YYYY-0001)';


--
-- Name: COLUMN remittances.commission_total; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittances.commission_total IS 'Total de comisión: (amount_sent * commission_percentage / 100) + commission_fixed';


--
-- Name: COLUMN remittances.amount_to_deliver; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittances.amount_to_deliver IS 'Monto final que recibe el destinatario: (amount_sent - commission_total) * exchange_rate';


--
-- Name: COLUMN remittances.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittances.status IS 'Estado actual de la remesa';


--
-- Name: COLUMN remittances.payer_phone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittances.payer_phone IS 'Contact phone of the person who paid, captured with the payment proof. Nullable; free-form.';


--
-- Name: COLUMN remittances.delivery_cost; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittances.delivery_cost IS 'Cash delivery cost added to what the sender pays (total = amount_sent + delivery_cost). Never deducted from amount_to_deliver. 0 for non-cash.';


--
-- Name: COLUMN remittances.shipping_zone_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittances.shipping_zone_id IS 'Shipping zone the delivery_cost was resolved from (cash only). NULL for non-cash or when the zone was deleted.';


--
-- Name: recalculate_remittance_at_current_rate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_remittance_at_current_rate(p_remittance_id uuid) RETURNS public.remittances
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rem          public.remittances%ROWTYPE;
  v_type         public.remittance_types%ROWTYPE;
  v_from_id      uuid;
  v_to_id        uuid;
  v_rate         numeric;
  v_inv          numeric;
  v_from_usd     numeric;
  v_to_usd       numeric;
  v_comm_pct     numeric;
  v_comm_fixed   numeric;
  v_comm_total   numeric;
  v_to_deliver   numeric;
BEGIN
  SELECT * INTO v_rem FROM public.remittances WHERE id = p_remittance_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'remittance_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT (
    v_rem.user_id = public.current_user_id()
    OR public.is_admin_user()
    OR public.is_super_admin()
  ) THEN
    RAISE EXCEPTION 'insufficient_privilege: not the owner of this remittance' USING ERRCODE = '42501';
  END IF;
  IF v_rem.status NOT IN ('payment_pending', 'payment_rejected') THEN
    RAISE EXCEPTION 'invalid_status: only payment_pending or payment_rejected remittances can be recalculated'
      USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_type FROM public.remittance_types WHERE id = v_rem.remittance_type_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'remittance_type_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_rem.currency_sent = v_rem.currency_delivered THEN
    v_rate := 1;
  ELSIF v_type.exchange_rate IS NOT NULL AND v_type.exchange_rate > 0 THEN
    v_rate := v_type.exchange_rate;
  ELSE
    SELECT id INTO v_from_id FROM public.currencies
      WHERE code = v_rem.currency_sent AND is_active = true LIMIT 1;
    SELECT id INTO v_to_id FROM public.currencies
      WHERE code = v_rem.currency_delivered AND is_active = true LIMIT 1;
    IF v_from_id IS NOT NULL AND v_to_id IS NOT NULL THEN
      SELECT rate INTO v_rate
      FROM public.exchange_rates
      WHERE from_currency_id = v_from_id AND to_currency_id = v_to_id AND is_active = true
      ORDER BY effective_date DESC
      LIMIT 1;
      IF v_rate IS NULL OR v_rate <= 0 THEN
        v_rate := NULL;
        SELECT rate INTO v_inv
        FROM public.exchange_rates
        WHERE from_currency_id = v_to_id AND to_currency_id = v_from_id AND is_active = true
        ORDER BY effective_date DESC
        LIMIT 1;
        IF v_inv IS NOT NULL AND v_inv <> 0 THEN
          v_rate := 1 / v_inv;
        END IF;
      END IF;
      IF v_rate IS NULL OR v_rate <= 0 THEN
        v_rate := NULL;
        SELECT rate_to_usd INTO v_from_usd FROM public.official_currency_rates
          WHERE currency_code = v_rem.currency_sent;
        SELECT rate_to_usd INTO v_to_usd FROM public.official_currency_rates
          WHERE currency_code = v_rem.currency_delivered;
        v_from_usd := COALESCE(v_from_usd, CASE v_rem.currency_sent WHEN 'USD' THEN 1 WHEN 'MLC' THEN 1 WHEN 'CUP' THEN 0.041 END);
        v_to_usd   := COALESCE(v_to_usd,   CASE v_rem.currency_delivered WHEN 'USD' THEN 1 WHEN 'MLC' THEN 1 WHEN 'CUP' THEN 0.041 END);
        IF v_from_usd IS NOT NULL AND v_to_usd IS NOT NULL AND v_to_usd <> 0 THEN
          v_rate := v_from_usd / v_to_usd;
        END IF;
      END IF;
    END IF;
    IF v_rate IS NULL OR v_rate <= 0 THEN
      v_rate := 1;
    END IF;
  END IF;
  v_comm_pct   := COALESCE(v_type.commission_percentage, 0);
  v_comm_fixed := COALESCE(v_type.commission_fixed, 0);
  v_comm_total := (v_rem.amount_sent * v_comm_pct / 100) + v_comm_fixed;
  v_to_deliver := (v_rem.amount_sent - v_comm_total) * v_rate;
  UPDATE public.remittances
  SET exchange_rate         = v_rate,
      commission_percentage = v_comm_pct,
      commission_fixed      = v_comm_fixed,
      commission_total      = round(v_comm_total, 2),
      amount_to_deliver     = round(v_to_deliver, 2),
      updated_at            = now()
  WHERE id = p_remittance_id
  RETURNING * INTO v_rem;
  RETURN v_rem;
END;
$$;


--
-- Name: redact_pii_jsonb(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.redact_pii_jsonb(data jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  result jsonb;
  key text;
  val jsonb;
  elem jsonb;
  arr jsonb := '[]'::jsonb;
BEGIN
  IF data IS NULL THEN
    RETURN NULL;
  END IF;

  CASE jsonb_typeof(data)
    WHEN 'object' THEN
      result := '{}'::jsonb;
      FOR key, val IN SELECT * FROM jsonb_each(data) LOOP
        result := result || jsonb_build_object(key, public.redact_pii_jsonb(val));
      END LOOP;
      RETURN result;
    WHEN 'array' THEN
      FOR elem IN SELECT * FROM jsonb_array_elements(data) LOOP
        arr := arr || jsonb_build_array(public.redact_pii_jsonb(elem));
      END LOOP;
      RETURN arr;
    WHEN 'string' THEN
      RETURN to_jsonb(
        regexp_replace(
          data #>> '{}',
          '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}',
          '[REDACTED_EMAIL]',
          'g'
        )
      );
    ELSE
      RETURN data;
  END CASE;
END;
$$;


--
-- Name: refresh_user_category(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_user_category(p_user_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_interaction_count integer;
  v_new_category text;
  v_old_category text;
BEGIN
  IF NOT is_admin_user() THEN
    RAISE EXCEPTION 'Access denied: admin role required';
  END IF;

  SELECT category_name INTO v_old_category
  FROM public.user_categories
  WHERE user_id = p_user_id;

  v_old_category := COALESCE(v_old_category, 'regular');
  v_interaction_count := public.count_user_interactions(p_user_id);
  v_new_category := public.get_category_from_interactions(v_interaction_count);

  IF v_new_category != v_old_category THEN
    INSERT INTO public.user_categories (user_id, category_name, assignment_reason, assigned_by)
    VALUES (p_user_id, v_new_category, 'automatic', NULL)
    ON CONFLICT (user_id) DO UPDATE
    SET category_name = v_new_category,
        updated_at = now();

    INSERT INTO public.user_category_history (user_id, old_category, new_category, change_reason)
    VALUES (p_user_id, v_old_category, v_new_category, 'Automatic recalculation');

    RETURN json_build_object(
      'success', true,
      'message', 'Category updated automatically',
      'old_category', v_old_category,
      'new_category', v_new_category,
      'interactions', v_interaction_count
    );
  ELSE
    RETURN json_build_object(
      'success', true,
      'message', 'Category unchanged',
      'category', v_new_category,
      'interactions', v_interaction_count
    );
  END IF;
END;
$$;


--
-- Name: release_order_inventory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_order_inventory(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_order public.orders%ROWTYPE;
  v_count integer;
BEGIN
  SELECT o.user_id INTO v_owner FROM public.orders o WHERE o.id = p_order_id;
  IF NOT FOUND THEN
    IF v_uid IS NOT NULL AND NOT public.is_admin_user() THEN
      RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
    END IF;
    RETURN jsonb_build_object('ok', false, 'reason', 'order_not_found', 'released', false);
  END IF;
  IF v_uid IS NOT NULL AND v_owner IS DISTINCT FROM v_uid AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;

  IF v_order.status IS DISTINCT FROM 'cancelled' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'order_not_cancelled', 'released', false);
  END IF;

  v_count := public._release_order_locked(p_order_id);

  RETURN jsonb_build_object(
    'ok', true,
    'reason', CASE WHEN v_count = 0 THEN 'nothing_to_release' ELSE NULL END,
    'released', v_count > 0
  );
END;
$$;


--
-- Name: release_stock_on_order_cancel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_stock_on_order_cancel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.stock_managed THEN
    -- Own subtransaction: a failing release must never make the owner's cancel fail. The
    -- failure is logged and the order stays cancelled with its reservation; the hourly
    -- expire_stale_order_reservations sweep heals that orphan.
    BEGIN
      PERFORM public._release_order_locked(NEW.id);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'release_stock_on_order_cancel: order % not released (%: %)', NEW.id, SQLSTATE, SQLERRM;
      INSERT INTO public.admin_destructive_ops_log (op_type, performed_by, details)
      VALUES ('stock_release_failed', COALESCE(auth.uid()::text, 'system'),
              jsonb_build_object('order_id', NEW.id, 'sqlstate', SQLSTATE, 'sqlerrm', SQLERRM));
    END;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: remove_manager_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_manager_role(p_manager_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  -- Check if current user is super_admin
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = v_user_id AND role = 'super_admin'
  ) THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Only super_admin can remove manager role'
    );
  END IF;

  -- Update user_profiles to set role back to user
  UPDATE public.user_profiles
  SET role = 'user'
  WHERE id = p_manager_id;

  -- Mark assignment as removed
  UPDATE public.manager_assignments
  SET removed_at = now()
  WHERE manager_id = p_manager_id
  AND removed_at IS NULL;

  RETURN json_build_object(
    'success', true,
    'message', 'Manager role removed successfully',
    'manager_id', p_manager_id
  );
END;
$$;


--
-- Name: reserve_order_inventory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_order_inventory(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_order public.orders%ROWTYPE;
  v_result jsonb;
  -- Max orders holding a 'reserved' allocation (any status) one customer may have at once.
  -- Configurable by super_admin (stock_max_open_reservations, default 5, bounds 1..50);
  -- a missing or invalid row falls back to the default and never fails the reserve.
  v_max_open_reservations integer := public._stock_policy_int('stock_max_open_reservations');
  v_open integer;
BEGIN
  -- Authorize on an unlocked read so strangers cannot queue on someone's row lock.
  -- An unknown id and someone else's order are indistinguishable to end users (no existence leak).
  SELECT o.user_id INTO v_owner FROM public.orders o WHERE o.id = p_order_id;
  IF NOT FOUND THEN
    IF v_uid IS NOT NULL AND NOT public.is_admin_user() THEN
      RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
    END IF;
    RETURN jsonb_build_object('ok', false, 'reason', 'order_not_found');
  END IF;
  IF v_uid IS NOT NULL AND v_owner IS DISTINCT FROM v_uid AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;

  IF NOT v_order.stock_managed THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'legacy_order');
  END IF;
  IF v_order.stock_reserved THEN
    RETURN jsonb_build_object('ok', true, 'reason', 'already_reserved');
  END IF;
  IF v_order.status IS DISTINCT FROM 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_order_state');
  END IF;

  -- Serialize the per-customer cap (order lock first, then this lock, then inventory).
  PERFORM pg_advisory_xact_lock(hashtext('reserve_cap:' || v_order.user_id::text));
  SELECT count(*) INTO v_open
    FROM public.orders o
   WHERE o.user_id = v_order.user_id
     AND o.id <> p_order_id
     AND o.stock_managed
     AND EXISTS (SELECT 1 FROM public.order_stock_allocations a
                  WHERE a.order_id = o.id AND a.state = 'reserved');

  IF v_open >= v_max_open_reservations THEN
    v_result := jsonb_build_object('ok', false, 'reason', 'too_many_open_reservations');
  ELSE
    v_result := public._reserve_order_locked(p_order_id);
  END IF;

  IF NOT (v_result ->> 'ok')::boolean THEN
    UPDATE public.orders
       SET status = 'cancelled',
           payment_status = 'rejected',
           rejection_reason = v_result ->> 'reason',
           updated_at = now()
     WHERE id = p_order_id;
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: reserve_zelle_account(character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_zelle_account(p_transaction_type character varying, p_amount numeric) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'p_amount must be a positive number';
  END IF;

  SELECT id INTO v_account_id
  FROM zelle_accounts
  WHERE is_active = true
    AND (
      (p_transaction_type = 'remittance' AND for_remittances = true) OR
      (p_transaction_type IN ('product', 'combo') AND for_products = true)
    )
    AND (current_daily_amount + p_amount) <= COALESCE(daily_limit, 999999)
    AND (current_monthly_amount + p_amount) <= COALESCE(monthly_limit, 999999)
    AND (current_daily_amount + p_amount) <= COALESCE(security_limit, 999999)
  ORDER BY priority_order ASC, last_used_at ASC NULLS FIRST
  LIMIT 1
  FOR UPDATE SKIP LOCKED;

  IF v_account_id IS NOT NULL THEN
    UPDATE zelle_accounts
    SET current_daily_amount = current_daily_amount + p_amount,
        current_monthly_amount = current_monthly_amount + p_amount,
        last_used_at = now(),
        updated_at = now()
    WHERE id = v_account_id;
  END IF;

  RETURN v_account_id;
END;
$$;


--
-- Name: FUNCTION reserve_zelle_account(p_transaction_type character varying, p_amount numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reserve_zelle_account(p_transaction_type character varying, p_amount numeric) IS 'DEPRECATED: mutable counters drift (no reset job, manual picks bypass them). Replaced by the read-only select_available_zelle_account over computed usage (zelle_account_usage). Kept only so the previously deployed frontend keeps working; do not call from new code.';


--
-- Name: reset_daily_zelle_counters(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_daily_zelle_counters() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE zelle_accounts
  SET
    current_daily_amount = 0,
    last_reset_date = CURRENT_DATE
  WHERE last_reset_date < CURRENT_DATE;
END;
$$;


--
-- Name: reset_monthly_zelle_counters(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_monthly_zelle_counters() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE zelle_accounts
  SET current_monthly_amount = 0
  WHERE EXTRACT(DAY FROM now()) = 1;
END;
$$;


--
-- Name: reset_stock_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_stock_policy() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  RETURN public._apply_stock_policy(48, 168, 5, 'stock_policy_reset');
END;
$$;


--
-- Name: restock_order_inventory(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restock_order_inventory(p_order_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_order public.orders%ROWTYPE;
  v_alloc record;
  v_count integer := 0;
  v_prev_rpc text;
BEGIN
  IF v_uid IS NOT NULL AND NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'reason_required', 'restocked', false);
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'order_not_found', 'restocked', false);
  END IF;
  IF v_order.status IS DISTINCT FROM 'cancelled' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'order_not_cancelled', 'restocked', false);
  END IF;

  PERFORM 1
     FROM public.inventory i
    WHERE i.id IN (
            SELECT a.inventory_id FROM public.order_stock_allocations a
             WHERE a.order_id = p_order_id AND a.state = 'consumed')
    ORDER BY i.id
      FOR UPDATE;

  -- Tell the inventory ledger trigger (20261014200000) that this write is already ledgered here.
  v_prev_rpc := current_setting('app.stock_rpc', true);
  PERFORM set_config('app.stock_rpc', 'on', true);

  FOR v_alloc IN
    SELECT a.id, a.inventory_id, a.quantity
      FROM public.order_stock_allocations a
     WHERE a.order_id = p_order_id AND a.state = 'consumed'
     ORDER BY a.inventory_id
  LOOP
    UPDATE public.inventory
       SET quantity = quantity + v_alloc.quantity
     WHERE id = v_alloc.inventory_id;

    UPDATE public.order_stock_allocations
       SET state = 'restocked', restocked_at = now(), updated_at = now()
     WHERE id = v_alloc.id;

    INSERT INTO public.inventory_movements
      (inventory_id, movement_type, quantity_change, reserved_change, reference_id, reference_type, notes, created_by)
    VALUES
      (v_alloc.inventory_id, 'restocked', v_alloc.quantity, 0, p_order_id, 'order',
       'Restocked from cancelled order ' || COALESCE(v_order.order_number, p_order_id::text)
         || ': ' || btrim(p_reason), v_uid);

    v_count := v_count + 1;
  END LOOP;

  PERFORM set_config('app.stock_rpc', COALESCE(v_prev_rpc, 'off'), true);

  IF v_count > 0 THEN
    UPDATE public.orders
       SET stock_reserved = false,
           stock_reserved_at = NULL
     WHERE id = p_order_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'reason', CASE WHEN v_count = 0 THEN 'nothing_to_restock' ELSE NULL END,
    'restocked', v_count > 0
  );
END;
$$;


--
-- Name: select_available_zelle_account(character varying, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.select_available_zelle_account(p_transaction_type character varying, p_amount numeric) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_account_id uuid;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'p_amount must be a positive number' USING ERRCODE = '22023';
  END IF;
  IF p_transaction_type IS NULL OR p_transaction_type NOT IN ('remittance', 'product', 'combo') THEN
    RAISE EXCEPTION 'invalid p_transaction_type: %', p_transaction_type USING ERRCODE = '22023';
  END IF;

  SELECT za.id INTO v_account_id
  FROM zelle_accounts za
  JOIN public.zelle_account_capacity(p_amount) cap ON cap.account_id = za.id
  WHERE za.is_active = true
    AND cap.fits
    AND (
      (p_transaction_type = 'remittance' AND za.for_remittances = true)
      OR (p_transaction_type IN ('product', 'combo') AND za.for_products = true)
    )
  ORDER BY za.priority_order ASC, cap.daily_usage ASC, za.account_name ASC
  LIMIT 1;

  RETURN v_account_id;
END;
$$;


--
-- Name: set_order_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_order_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NEW.order_number IS NULL THEN
        NEW.order_number := public.generate_order_number();
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: set_payment_method_enabled(text, text, boolean, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_payment_method_enabled(p_code text, p_flow text, p_enabled boolean, p_reason text DEFAULT NULL::text, p_confirm_last boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row       public.payment_methods%ROWTYPE;
  v_prev      boolean;
  v_remaining integer;
  v_reason    text;
  v_orders    boolean;
  v_remit     boolean;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'payment_method_forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_flow IS NULL OR p_flow NOT IN ('orders', 'remittances') THEN
    RAISE EXCEPTION 'payment_method_invalid_flow' USING ERRCODE = 'P0001';
  END IF;

  IF p_enabled IS NULL THEN
    RAISE EXCEPTION 'payment_method_invalid_flow' USING ERRCODE = 'P0001';
  END IF;

  v_reason := NULLIF(btrim(COALESCE(p_reason, '')), '');
  IF v_reason IS NOT NULL AND char_length(v_reason) > 200 THEN
    RAISE EXCEPTION 'payment_method_reason_too_long' USING ERRCODE = 'P0001';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('payment_methods'));

  SELECT * INTO v_row
    FROM public.payment_methods
   WHERE code = p_code
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'payment_method_not_found' USING ERRCODE = 'P0001';
  END IF;

  v_prev := CASE p_flow WHEN 'orders' THEN v_row.enabled_for_orders ELSE v_row.enabled_for_remittances END;

  IF v_prev = p_enabled THEN
    RETURN jsonb_build_object(
      'code', v_row.code,
      'available', v_row.available,
      'enabled_for_orders', v_row.enabled_for_orders,
      'enabled_for_remittances', v_row.enabled_for_remittances,
      'disabled_reason', v_row.disabled_reason,
      'updated_at', v_row.updated_at,
      'updated_by', v_row.updated_by
    );
  END IF;

  IF p_enabled AND NOT v_row.available THEN
    RAISE EXCEPTION 'payment_method_unavailable' USING ERRCODE = 'P0001';
  END IF;

  IF NOT p_enabled THEN
    SELECT count(*) INTO v_remaining
      FROM public.payment_methods pm
     WHERE pm.code <> p_code
       AND pm.available
       AND CASE p_flow WHEN 'orders' THEN pm.enabled_for_orders ELSE pm.enabled_for_remittances END;

    IF v_remaining = 0 AND NOT COALESCE(p_confirm_last, false) THEN
      RAISE EXCEPTION 'payment_method_last_enabled' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  v_orders := CASE WHEN p_flow = 'orders' THEN p_enabled ELSE v_row.enabled_for_orders END;
  v_remit  := CASE WHEN p_flow = 'remittances' THEN p_enabled ELSE v_row.enabled_for_remittances END;

  UPDATE public.payment_methods
     SET enabled_for_orders      = v_orders,
         enabled_for_remittances = v_remit,
         disabled_reason = CASE
           WHEN v_orders AND v_remit THEN NULL
           WHEN NOT p_enabled AND v_reason IS NOT NULL THEN v_reason
           ELSE disabled_reason
         END,
         updated_at = now(),
         updated_by = auth.uid()
   WHERE code = p_code
   RETURNING * INTO v_row;

  INSERT INTO public.activity_logs (action, entity_type, entity_id, performed_by, description, metadata)
  VALUES (
    'payment_method_toggled',
    'payment_method',
    NULL,
    auth.uid()::text,
    format('Payment method %s %s for %s', p_code, CASE WHEN p_enabled THEN 'enabled' ELSE 'disabled' END, p_flow),
    jsonb_build_object(
      'code', p_code,
      'flow', p_flow,
      'enabled', p_enabled,
      'previous', v_prev,
      'confirm_last', COALESCE(p_confirm_last, false),
      'reason', v_reason
    )
  );

  RETURN jsonb_build_object(
    'code', v_row.code,
    'available', v_row.available,
    'enabled_for_orders', v_row.enabled_for_orders,
    'enabled_for_remittances', v_row.enabled_for_remittances,
    'disabled_reason', v_row.disabled_reason,
    'updated_at', v_row.updated_at,
    'updated_by', v_row.updated_by
  );
END;
$$;


--
-- Name: set_stock_policy(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_stock_policy(p_unpaid_hours integer, p_proof_hours integer, p_max_open integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;

  IF p_unpaid_hours IS NULL OR p_unpaid_hours NOT BETWEEN 6 AND 720 THEN
    RAISE EXCEPTION 'invalid_unpaid_hours: must be between 6 and 720' USING ERRCODE = '22023';
  END IF;
  IF p_proof_hours IS NULL OR p_proof_hours NOT BETWEEN 24 AND 2160 THEN
    RAISE EXCEPTION 'invalid_proof_hours: must be between 24 and 2160' USING ERRCODE = '22023';
  END IF;
  IF p_proof_hours < p_unpaid_hours THEN
    RAISE EXCEPTION 'invalid_proof_hours: must not be lower than the unpaid window' USING ERRCODE = '22023';
  END IF;
  IF p_max_open IS NULL OR p_max_open NOT BETWEEN 1 AND 50 THEN
    RAISE EXCEPTION 'invalid_max_open: must be between 1 and 50' USING ERRCODE = '22023';
  END IF;

  RETURN public._apply_stock_policy(p_unpaid_hours, p_proof_hours, p_max_open, 'stock_policy_updated');
END;
$$;


--
-- Name: set_user_role(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_user_role(target_user_id uuid, new_role text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF new_role NOT IN ('user','admin','super_admin') THEN
    RAISE EXCEPTION 'Role inválido: %', new_role;
  END IF;

  UPDATE public.user_profiles
  SET role = new_role, updated_at = now()
  WHERE user_id = target_user_id;
END;
$$;


