--
-- Name: update_user_category_manual(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_category_manual(p_user_id uuid, p_new_category text, p_reason text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin_id uuid := auth.uid();
  v_old_category text;
BEGIN
  -- Check if requester is admin or manager
  IF NOT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = v_admin_id
    AND role IN ('admin', 'super_admin', 'manager')
  ) THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Only admin or manager can change categories'
    );
  END IF;

  -- Validate new category
  IF p_new_category NOT IN ('regular', 'pro', 'vip') THEN
    RETURN json_build_object(
      'success', false,
      'error', 'Invalid category. Must be: regular, pro, or vip'
    );
  END IF;

  -- Get old category
  SELECT category_name INTO v_old_category
  FROM public.user_categories
  WHERE user_id = p_user_id;

  v_old_category := COALESCE(v_old_category, 'regular');

  -- Update or insert category
  INSERT INTO public.user_categories (user_id, category_name, assigned_by, assignment_reason)
  VALUES (p_user_id, p_new_category, v_admin_id, 'manual')
  ON CONFLICT (user_id) DO UPDATE
  SET category_name = p_new_category,
      assigned_by = v_admin_id,
      assignment_reason = 'manual',
      updated_at = now();

  -- Record in history
  INSERT INTO public.user_category_history (user_id, old_category, new_category, changed_by, change_reason)
  VALUES (p_user_id, v_old_category, p_new_category, v_admin_id, COALESCE(p_reason, 'Manual update'));

  RETURN json_build_object(
    'success', true,
    'message', 'Category updated successfully',
    'user_id', p_user_id,
    'old_category', v_old_category,
    'new_category', p_new_category,
    'changed_by', v_admin_id
  );
END;
$$;


--
-- Name: update_zelle_account_usage(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_zelle_account_usage(p_account_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_admin_user() THEN
    RAISE EXCEPTION 'No autorizado: se requiere rol admin' USING ERRCODE = '42501';
  END IF;

  UPDATE zelle_accounts
  SET
    current_daily_amount = GREATEST(0, current_daily_amount + p_amount),
    current_monthly_amount = GREATEST(0, current_monthly_amount + p_amount),
    last_used_at = now(),
    updated_at = now()
  WHERE id = p_account_id;
END;
$$;


--
-- Name: upsert_my_profile(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_my_profile(p_full_name text, p_avatar_url text, p_email text DEFAULT NULL::text) RETURNS TABLE(id uuid, user_id uuid, email text, role text, is_enabled boolean, full_name text, avatar_url text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  INSERT INTO public.user_profiles (user_id, email, full_name, avatar_url, role, is_enabled)
  VALUES (
    auth.uid(),
    COALESCE(p_email, ''),
    p_full_name,
    p_avatar_url,
    'user',
    true
  )
  ON CONFLICT (user_id) DO UPDATE
  SET full_name = EXCLUDED.full_name,
      avatar_url = EXCLUDED.avatar_url,
      updated_at = now()
  RETURNING
    public.user_profiles.id,
    public.user_profiles.user_id,
    public.user_profiles.email,
    public.user_profiles.role,
    public.user_profiles.is_enabled,
    public.user_profiles.full_name,
    public.user_profiles.avatar_url,
    public.user_profiles.created_at,
    public.user_profiles.updated_at;
END;
$$;


--
-- Name: zelle_account_capacity(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.zelle_account_capacity(p_amount numeric DEFAULT NULL::numeric) RETURNS TABLE(account_id uuid, daily_usage numeric, monthly_usage numeric, fits boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT za.id,
         u.daily_usage,
         u.monthly_usage,
         (
           p_amount IS NULL
           OR (
             (COALESCE(za.daily_limit, 0)    = 0 OR u.daily_usage   + p_amount <= za.daily_limit)
             AND (COALESCE(za.monthly_limit, 0)  = 0 OR u.monthly_usage + p_amount <= za.monthly_limit)
             AND (COALESCE(za.security_limit, 0) = 0 OR u.daily_usage   + p_amount <= za.security_limit)
           )
         )
  FROM zelle_accounts za
  JOIN public.zelle_account_usage() u ON u.account_id = za.id
$$;


--
-- Name: zelle_account_usage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.zelle_account_usage(p_account_id uuid DEFAULT NULL::uuid) RETURNS TABLE(account_id uuid, daily_usage numeric, monthly_usage numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tz       constant text := 'America/New_York';
  v_currency constant text := 'USD';
  v_day0     timestamptz;
  v_month0   timestamptz;
BEGIN
  v_day0   := date_trunc('day',   now() AT TIME ZONE v_tz) AT TIME ZONE v_tz;
  v_month0 := date_trunc('month', now() AT TIME ZONE v_tz) AT TIME ZONE v_tz;

  RETURN QUERY
  WITH movements AS (
    SELECT o.zelle_account_id AS aid, o.created_at AS ts, o.total_amount AS amt
    FROM orders o
    JOIN currencies c ON c.id = o.currency_id
    WHERE o.zelle_account_id IS NOT NULL
      AND c.code = v_currency
      AND o.status IS DISTINCT FROM 'cancelled'
      AND o.payment_status IS DISTINCT FROM 'rejected'
      AND o.created_at >= v_month0
    UNION ALL
    SELECT r.zelle_account_id, r.created_at, r.amount_sent + COALESCE(r.delivery_cost, 0)
    FROM remittances r
    WHERE r.zelle_account_id IS NOT NULL
      AND r.currency_sent = v_currency
      AND r.status NOT IN ('cancelled', 'payment_rejected')
      AND r.created_at >= v_month0
  )
  SELECT za.id,
         COALESCE(SUM(m.amt) FILTER (WHERE m.ts >= v_day0), 0)::numeric,
         COALESCE(SUM(m.amt), 0)::numeric
  FROM zelle_accounts za
  LEFT JOIN movements m ON m.aid = za.id
  WHERE p_account_id IS NULL OR za.id = p_account_id
  GROUP BY za.id;
END;
$$;


