    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    email text NOT NULL,
    role text DEFAULT 'user'::text,
    is_enabled boolean DEFAULT true,
    full_name text,
    avatar_url text,
    CONSTRAINT user_profiles_id_user_id_check CHECK ((id = user_id)),
    CONSTRAINT user_profiles_role_check CHECK ((role = ANY (ARRAY['user'::text, 'admin'::text, 'super_admin'::text, 'manager'::text])))
);


--
-- Name: order_analytics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.order_analytics WITH (security_invoker='true') AS
 SELECT o.id,
    o.order_number,
    o.created_at,
    o.validated_at,
    o.status,
    o.payment_status,
    o.total_amount,
    o.shipping_cost,
    sz.transport_cost,
    sz.province_name,
    (o.shipping_address ->> 'municipality'::text) AS municipality,
    up.full_name AS customer_name,
    up.email AS customer_email,
    c.code AS currency_code
   FROM (((public.orders o
     LEFT JOIN public.shipping_zones sz ON ((o.shipping_zone_id = sz.id)))
     LEFT JOIN public.user_profiles up ON ((o.user_id = up.user_id)))
     LEFT JOIN public.currencies c ON ((o.currency_id = c.id)));


