--
-- Name: remittance_types; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.remittance_types (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(200) NOT NULL,
    currency_code character varying(10) NOT NULL,
    delivery_currency character varying(10) NOT NULL,
    exchange_rate numeric(12,4) NOT NULL,
    commission_percentage numeric(20,10) DEFAULT 0,
    commission_fixed numeric(10,2) DEFAULT 0,
    min_amount numeric(10,2) NOT NULL,
    max_amount numeric(10,2),
    delivery_method character varying(50) NOT NULL,
    max_delivery_days integer DEFAULT 3,
    warning_days integer DEFAULT 2,
    is_active boolean DEFAULT true,
    display_order integer DEFAULT 0,
    description text,
    icon character varying(50),
    notes text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    created_by uuid
);


--
-- Name: TABLE remittance_types; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.remittance_types IS 'Configuración de tipos de remesas disponibles';


--
-- Name: COLUMN remittance_types.exchange_rate; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittance_types.exchange_rate IS 'Tasa de cambio: 1 unidad de currency_code = X unidades de delivery_currency';


--
-- Name: COLUMN remittance_types.commission_percentage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittance_types.commission_percentage IS 'Porcentaje de comisión sobre el monto (0-100)';


--
-- Name: COLUMN remittance_types.commission_fixed; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittance_types.commission_fixed IS 'Comisión fija adicional en currency_code';


--
-- Name: COLUMN remittance_types.max_delivery_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittance_types.max_delivery_days IS 'Días máximos desde validación hasta entrega';


--
-- Name: COLUMN remittance_types.warning_days; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.remittance_types.warning_days IS 'Días para mostrar alerta amarilla antes del máximo';


--
