    updated_at timestamp with time zone DEFAULT now()
);


--
-- Name: TABLE system_messages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.system_messages IS 'Admin-configurable system messages for checkout and support';


--
-- Name: testimonials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.testimonials (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    user_id uuid NOT NULL,
    rating integer NOT NULL,
    comment text NOT NULL,
    user_photo text,
    is_visible boolean DEFAULT false,
    is_featured boolean DEFAULT false,
    order_id uuid,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT testimonials_rating_check CHECK (((rating >= 1) AND (rating <= 5)))
);


--
-- Name: user_alerts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_alerts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    alert_type character varying(50) NOT NULL,
    severity character varying(20) DEFAULT 'warning'::character varying,
    title text NOT NULL,
    message text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb,
    is_read boolean DEFAULT false,
    is_dismissed boolean DEFAULT false,
    action_required boolean DEFAULT true,
    action_url character varying(255),
    created_at timestamp with time zone DEFAULT now(),
    read_at timestamp with time zone,
    dismissed_at timestamp with time zone,
    expires_at timestamp with time zone
);


--
-- Name: TABLE user_alerts; Type: COMMENT; Schema: public; Owner: -
