--
-- Name: user_categories; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_categories (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    category_name text DEFAULT 'regular'::text NOT NULL,
    assigned_at timestamp with time zone DEFAULT now(),
    assigned_by uuid,
    assignment_reason text DEFAULT 'automatic'::text,
    effective_from timestamp with time zone DEFAULT now(),
    effective_to timestamp with time zone,
    referral_count integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT user_categories_category_check CHECK ((category_name = ANY (ARRAY['regular'::text, 'pro'::text, 'vip'::text])))
);


--
-- Name: TABLE user_categories; Type: COMMENT; Schema: public; Owner: -
