    bank_name text,
    account_holder text,
    is_active boolean DEFAULT true,
    for_products boolean DEFAULT true,
    for_remittances boolean DEFAULT true,
    daily_limit numeric(12,2),
    monthly_limit numeric(12,2),
    current_daily_amount numeric(12,2) DEFAULT 0,
    current_monthly_amount numeric(12,2) DEFAULT 0,
    last_reset_date date DEFAULT CURRENT_DATE,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    security_limit numeric DEFAULT 1000.00,
    priority_order integer DEFAULT 0,
    notes text,
    last_used_at timestamp with time zone,
    show_email boolean DEFAULT true NOT NULL,
    show_phone boolean DEFAULT true NOT NULL,
    CONSTRAINT zelle_accounts_at_least_one_contact_visible CHECK ((show_email OR show_phone))
);


