--
-- Name: user_alerts Admins can manage all alerts; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can manage all alerts" ON public.user_alerts USING ((EXISTS ( SELECT 1
   FROM public.user_profiles
  WHERE ((user_profiles.id = ( SELECT auth.uid() AS uid)) AND (user_profiles.role = ANY (ARRAY['admin'::text, 'super_admin'::text]))))));


--
-- Name: user_alerts Service can insert alerts; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Service can insert alerts" ON public.user_alerts FOR INSERT WITH CHECK (true);


--
-- Name: user_alerts Users can update own alerts; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Users can update own alerts" ON public.user_alerts FOR UPDATE USING ((( SELECT auth.uid() AS uid) = user_id)) WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));


--
-- Name: user_alerts Users can view own alerts; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Users can view own alerts" ON public.user_alerts FOR SELECT USING ((( SELECT auth.uid() AS uid) = user_id));


